def prepare_existing(apps, schema_editor):
    import re
    import unicodedata
    from utils.general import cht_to_chs
    Catalog = apps.get_model('web', 'Channel_list')
    Channel = apps.get_model('web', 'Channel')
    seen = {}
    for row in Catalog.objects.order_by('id').iterator():
        if row.source == 'g4tv':
            row.source = '4gtv'
        key = (row.source, row.out_channel_id)
        if key in seen:
            keeper = Catalog.objects.get(pk=seen[key])
            if not keeper.inner_name and row.inner_name:
                keeper.inner_name, keeper.inner_channel_id = row.inner_name, row.inner_channel_id
                keeper.save()
            row.delete()
            continue
        seen[key] = row.pk
        row.normalized_name = re.sub(r'\s+', '', unicodedata.normalize('NFKC', cht_to_chs(row.out_name))).casefold()
        row.save()
    Channel.objects.filter(last_program_date__isnull=True).update(last_program_date=datetime.date(2000, 1, 1))
    for channel in Channel.objects.all().iterator():
        if re.search(r'(imxd|mxdyeah|crestekk)', channel.logo or ''):
            channel.logo = ''
        channel.channel_id = channel.channel_id.replace('<g4tv:', '<4gtv:')
        if channel.source == 'g4tv':
            channel.source = '4gtv'
        channel.save()


